import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch BM stories: the same defendant, back in this court.
extension FollowUpCases {
    static let batchBM: [CaseTemplate] = [caregiverAccountBack, brakeLinesBack, stalkerCoworkerBack, armedConvenienceRobberyBack, trafficStopBribeBack, onePunchBack, wrongDoorBack, romanceScamBack, busStopPurseBack, nurseryNightBack, harborDisappearanceBack, driveByBack, nightNurseBack, collegeHouseBack, movieSetGunBack, eyeDropPoisoningBack, ponziAdvisorBack, chopShopBack, odometerRollbackBack, motelCarbonMonoxideBack, nursingHomeNeglectBack, stolenValorBack, boatLandingBack, dragRaceDeathBack, beachHouseBack]

    static let caregiverAccountBack = SmallCases.make(
        key: "story.followup.caregiverAccountBack",
        category: .whiteCollar,
        headlines: ["Church Volunteer Driver Accused of Taking Older Neighbor's Savings", "Defendant From Caregiver Case Faces Elder Exploitation Charge"],
        law: "exploitationElder",
        spec: "Knowingly used the funds of {V}, an older adult, through deception and undue influence, taking $9,400, on or about {DATE}.",
        ages: 29...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} began driving {V}, 84, to church and the pharmacy as a volunteer. Over three months $9,400 left {V}'s checking account through checks made out to {DL}. {V}'s niece found the stubs. {DL} says {V} wrote them as thank-you gifts.",
        state: [E(.document, 3, "Check Stubs", "Six checks to {D} totaling $9,400, all signed in a shaky hand."), E(.digital, 2, "Bank Alerts", "Alerts show each check cashed the same day it was written.")],
        defense: [E(.statement, 1, "Thank-You Gifts", "{DL} says {V} wanted to repay the rides.")],
        role: "Niece of the victim",
        exam: [.direct("How are you related to the victim?", "\"{V} is my aunt, who is eighty-four, and I help watch over {V.his} affairs.\""), .direct("What did you discover?", "\"That ninety-four hundred dollars had left {V.his} checking account in three months, through checks made out to {DL}.\""), .direct("Who is {DL}?", "\"A volunteer who drove my aunt to church and to the pharmacy, and whom {V.he} trusted.\""), .direct("What do the check stubs show?", "\"Six checks to {DL}, totaling ninety-four hundred dollars, all signed in a shaky hand.\""), .direct("What do the bank alerts show?", "\"Each check was cashed the same day it was written, at the same branch.\""), .direct("What did {DL} say?", "\"{D.He} said my aunt wanted to repay the rides with thank-you gifts.\""), .cross("Your aunt trusted {DL}?", "\"Very much, and {V.he} says {D.he} was kind to {V.him}.\""), .cross("Your aunt has memory problems?", "\"Some, and {V.he} sometimes can't recall what {V.he} signs, or even who {V.he} signed it for.\""), .cross("The checks were signed by {V.him}?", "\"They were signed, but the writing is shaky, and I can't say how clearly {V.he} understood.\""), .cross("{DL} didn't take cash?", "\"No, {D.he} never took cash from {V.him}. It was only checks, each cashed the same day.\""), .cross("{DL} hasn't repaid anything?", "\"No, {D.he} hasn't repaid anything, and {D.he} has stopped returning our calls.\"")],
        theory: ("{D} took money from an elderly person who trusted {D.him}.", "A volunteer who accepted gifts."),
        allocution: "\"I started driving {V} to church and the pharmacy as a volunteer, and I never asked for money. {V.He} insisted on writing me checks as thank-you gifts, and I took them because refusing seemed to hurt {V.him}. I also helped with the checkbook because {V.his} hands shake. I'm sorry that the niece saw it as something else, and I'll show every stub.\"",
        truths: ("{DL} had a prior case in this court and filled in the amounts on the checks before {V} signed.", "{V} told a bank teller {V.he} meant to give {DL} the money, and the teller wrote it down."),
        defendant: [.direct("Did you take advantage of the victim?", "\"No. {V.He} wanted to thank me for the rides, and {V.he} gave me the checks. I never asked for them.\""), .direct("How often did you drive {V.him}?", "\"Several times a week for three months, to church, to the doctor, and to the pharmacy.\""), .direct("Why were the checks so large?", "\"{V.He} insisted. {V.He} said {V.he} had no one else to leave {V.his} money to.\""), .direct("Did you ever pressure {V.him}?", "\"No. I told {V.him} it was too much, and {V.he} said it was {V.his} choice.\""), .direct("Did you know about {V.his} memory problems?", "\"I knew {V.he} forgot things, but {V.he} seemed clear when {V.he} wrote the checks.\""), .direct("What would you tell {V.his} niece?", "\"I'm sorry for the worry. I'll give back any money the court says I shouldn't have.\""), .cross("You've been accused of taking money from an older person before, haven't you?", "\"Yes, and I was cleared. I know why people look at me.\""), .cross("Ninety-four hundred dollars is a lot for rides to church?", "\"It is a large amount for rides, and I should have refused it when {V.he} offered it.\""), .cross("The bank alerts show each check was cashed the same day?", "\"They do show it was cashed the same day, and I can see how that looks.\""), .cross("You'll return the money if the court orders?", "\"Yes, I'll return the money if the court orders it, as soon as I can.\""), .cross("You'll stop driving {V.him}?", "\"Yes, if {V.his} family wants me to stop driving {V.him}, I'll stop and stay away from {V.him}.\"")],
        openings: ("{D} began driving {V}, 84, to church and the pharmacy as a volunteer, and over three months $9,400 left {V}'s checking account through checks made out to {D}, which {V}'s niece found in the stubs, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} wrote the checks as thank-you gifts for the rides. A grateful person may give a gift to a helper."),
        closings: ("$9,400 left {V}'s account over three months in checks made out to {D}, and after {PRIOR} {DL} knew exactly what an 84-year-old's trust means.", "Checks written as thank-you gifts are lawful. The State must prove {V} did not understand what {V.he} was signing, and a niece's reading of stubs shows only the amounts."),
        timeline: [(-90, "{DL} begins driving {V} to church."), (-30, "The checks start."), (0, "The niece finds the stubs.")],
        identified: "The victim's niece found the check stubs.",
        aggravating: ["The victim was an older adult"],
        mood: .wantsConviction)

    static let brakeLinesBack = SmallCases.make(
        key: "story.followup.brakeLinesBack",
        category: .property,
        headlines: ["Contractor Slashes Tires on Rival's Trucks", "Defendant From Brake Line Case Back Over a Business Dispute"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured the personal property of {V}, four truck tires worth about $1,100, on {DATE}.",
        ages: 35...68,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was seen at a lumber yard lot where {V}, a rival contractor, keeps work trucks. In the morning, all four tires on one truck were cut. {DL} says {D.he} only walked through the lot to look at lumber.",
        state: [E(.video, 3, "Lot Camera", "A figure in a work jacket crouches beside the truck wheels."), E(.physical, 2, "Cut Tires", "Four tires with clean knife cuts through the sidewalls.", .search)],
        defense: [E(.statement, 1, "Walk Through", "{DL} says {D.he} was at the lot for lumber.")],
        role: "Lumber yard manager",
        exam: [.direct("What is your position?", "\"I'm the manager of a lumber yard, where contractors keep work trucks in a back lot.\""), .direct("What happened that morning?", "\"One of the work trucks had all four tires cut, with clean knife cuts through the sidewalls.\""), .direct("Whose truck was it?", "\"{V}'s, a contractor who competes with {DL} for jobs in the county.\""), .direct("What does the lot camera show?", "\"A figure in a work jacket crouching beside the truck's wheels, late at night.\""), .direct("What was the cost?", "\"About eleven hundred dollars for four new tires, and a day of lost work.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} only walked through the lot to buy lumber.\""), .cross("The yard is open to the public?", "\"During the day, yes, but the gate is closed at night.\""), .cross("The figure's face isn't visible?", "\"No, the camera angle is poor, and the person's face is turned away throughout the video.\""), .cross("{DL} visited the yard that day?", "\"Yes, {D.he} came to the yard earlier in the afternoon, and bought some lumber.\""), .cross("The tires were cut with a knife?", "\"Yes, the tires were cut with a knife, and the cuts were clean and deep.\""), .cross("{DL} and {V} compete for jobs?", "\"Yes, and they had a dispute over a bid last month.\"")],
        theory: ("{D} cut a rival's tires.", "A customer who was only buying lumber."),
        allocution: "\"I walked through that lumber yard lot to price lumber, and I carried a plain brown jacket and nothing else. I did not touch any truck, and I did not cut any tire. I'm sorry that {V} lost four tires and a day's work. I hope the court will see that a walk through a lot isn't proof.\"",
        truths: ("{DL} had a prior case in this court against the same industry and kept a pocketknife with rubber fibers on the blade.", "A different contractor had threatened {V} that week, and the jacket on the video had a patch {DL} does not own."),
        defendant: [.direct("Did you cut the truck's tires?", "\"No. I was at the lumber yard to buy lumber, and I walked through the lot. I didn't touch any truck.\""), .direct("Why were you at the yard at night?", "\"I wasn't. I went in the afternoon, and I left before closing.\""), .direct("Who do you think was on the video?", "\"I don't know. A figure in a work jacket, which many contractors wear.\""), .direct("What was your dispute with {V}?", "\"We bid on the same job, and he won it. I was disappointed, but I'd never hurt his truck.\""), .direct("What did you do when the deputy came?", "\"I told {OFF.him} where I was that night, and I showed {OFF.him} my phone.\""), .direct("What would you tell {V}?", "\"I'm sorry about your tires. It wasn't me, and I hope they find who did it.\""), .cross("You've been charged with damaging a rival's property before, haven't you?", "\"Yes, and I told the court I'd compete fairly. I'm doing that.\""), .cross("You were at the yard on the day of the cut tires?", "\"I was, in the afternoon, and I can explain why.\""), .cross("A work jacket like yours is on the video?", "\"It is a common jacket, and many men in this county have the same one.\""), .cross("You'll give the deputy your phone records?", "\"Yes, I'll give the deputy my phone records for that night, and my receipts.\""), .cross("You'll stay away from {V}'s trucks?", "\"Yes, I'll stay away from {V}'s trucks and from that lot completely.\"")],
        openings: ("{D} was seen at a lumber yard lot where {V}, a rival contractor, keeps work trucks, and in the morning all four tires on one truck were cut, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} only walked through the lot to look at lumber, as contractors do. {D} did not cut anything."),
        closings: ("{D} was seen on the lot where {V}'s trucks sit, all four tires on one truck were cut in the morning, and with {PRIOR} already on {D.his} record, {DL} knew exactly whose truck it was.", "A contractor looking at lumber is not a vandal, and a sighting is not proof. The State must prove {D} cut the tires."),
        timeline: [(-1, "{DL} visits the lumber yard."), (0, "3 a.m.: the tires are cut."), (0, "7 a.m.: {V} finds the truck.")],
        identified: "The lot camera footage.",
        mood: .indifferent)

    static let stalkerCoworkerBack = SmallCases.make(
        key: "story.followup.stalkerCoworkerBack",
        category: .cyber,
        headlines: ["Fake Social Media Accounts Follow Gym Trainer's Every Move", "Defendant From Stalking Case Charged With Cyberstalking"],
        law: "cyberstalking",
        spec: "Repeatedly sent electronic messages to {V}, a gym trainer, with intent to torment, on or about {DATE}.",
        ages: 24...63,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V}, a personal trainer at a new gym, got dozens of messages from accounts that knew {V}'s class schedule and car. {V} traced one account to {D}'s phone number. {DL} says {D.he} only sent a few friendly notes as a member.",
        state: [E(.digital, 3, "Account Records", "Seven accounts tied to {D}'s phone number sent 61 messages in six weeks."), E(.document, 2, "Screenshots", "Messages quote {V}'s class times and parking spot.")],
        defense: [E(.statement, 1, "Friendly Notes", "{DL} says only a few messages were meant to be nice.")],
        role: "Gym manager",
        exam: [.direct("What is your position?", "\"I'm the manager of a gym, and I received a complaint from a trainer about threatening messages.\""), .direct("What was reported?", "\"The trainer had received dozens of messages from several accounts that knew {V.his} class schedule and car.\""), .direct("What did the account records show?", "\"Seven accounts tied to {DL}'s phone number sent sixty-one messages in six weeks.\""), .direct("What did the screenshots show?", "\"Messages quoting {V}'s class times and parking spot, and comments about {V.his} clothing.\""), .direct("How did {V} react?", "\"{V.He} was frightened, and {V.he} asked me to walk {V.him} to {V.his} car after each shift.\""), .direct("What did {DL} say?", "\"{D.He} said only a few of the messages were meant to be friendly.\""), .cross("{DL} works at the gym?", "\"{D.He} is a member, who trains there several times a week.\""), .cross("{DL} doesn't have a history with {V}?", "\"They had spoken a few times at the front desk.\""), .cross("The messages weren't threats?", "\"Most of them were creepy but not violent, though some commented on {V.his} clothes.\""), .cross("{DL} stopped when told?", "\"No, {D.he} didn't stop. {D.He} created new accounts each time one was blocked.\""), .cross("You banned {DL} from the gym?", "\"Yes, I banned {D.him} from the gym after the second complaint came in.\"")],
        theory: ("{D} sent a steady stream of messages through fake accounts.", "A member who sent friendly notes."),
        allocution: "\"I sent two friendly welcome messages as a member of that gym, and that is all. My phone was locked, and I don't know how my number was used for the rest. I'm sorry that {V} was frightened by so many messages. I'll never contact {V.him} again, and I hope the one responsible is found.\"",
        truths: ("{DL} had a prior case in this court for the same behavior and made all seven accounts on the gym's Wi-Fi.", "Only two accounts used {DL}'s number, and the rest were made by another member who had been banned."),
        defendant: [.direct("Did you send those messages?", "\"I sent some, but I meant them to be friendly. I never meant to frighten anyone.\""), .direct("Why did you use several accounts?", "\"My first account was blocked, so I made new ones. I wasn't trying to hide, only to keep talking.\""), .direct("How did you know {V.his} schedule?", "\"It's posted on the gym's wall, and I saw {V.his} car in the lot.\""), .direct("Did you mean to torment {V.him}?", "\"No. I thought {V.he}'d appreciate the attention. I see now that I was wrong.\""), .direct("What did you do when you were banned?", "\"I stopped after the ban, and I haven't sent anything since that week.\""), .direct("What would you tell {V}?", "\"I'm sorry for frightening you. I'll never contact you again.\""), .cross("You've been told to stop contacting someone before, haven't you?", "\"Yes, and I told the court I'd listen. I didn't.\""), .cross("Sixty-one messages in six weeks is a lot?", "\"It is a lot, and I understand how it must have felt to {V.him}.\""), .cross("You made new accounts after being blocked?", "\"I did make new accounts after being blocked, and that was wrong.\""), .cross("You'll delete every account?", "\"Yes, I'll delete every one of those accounts today, and I'll show the deputy.\""), .cross("You'll stay away from the gym?", "\"Yes, I'll stay away from the gym and from {V.him}, for as long as the court says.\"")],
        openings: ("{V}, a personal trainer at a new gym, got dozens of messages from accounts that knew {V}'s class schedule and car, and {V} traced one account to {D}'s phone number, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D} only sent a few friendly notes as a member, and did not send dozens of messages. The other accounts are not {D}'s."),
        closings: ("Dozens of messages came from accounts that knew {V}'s schedule and car, one traced to {D}'s number, and having faced {PRIOR} before, {DL} understood exactly how that feels to a trainer.", "A few friendly notes from a member are not a campaign of messages. The State must prove {D} sent all of them."),
        timeline: [(-42, "{DL} joins the gym."), (-30, "The first message arrives."), (0, "{V} reports the accounts.")],
        identified: "Phone number on the account records.",
        mood: .sympathetic)

    static let armedConvenienceRobberyBack = SmallCases.make(
        key: "story.followup.armedConvenienceRobberyBack",
        category: .robbery,
        headlines: ["Pizza Driver Shoved and Robbed of Tips and Pay Envelope", "Defendant From Convenience Store Case Charged in New Robbery"],
        law: "commonLawRobbery",
        spec: "Took cash from the person of {V}, a pizza delivery driver, by force, on {DATE}.",
        ages: 19...48,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a pizza order sent {V} to an apartment lot, where a person shoved {V} against the car and took $240 in tips and cash. A phone number on the order was traced to {D}. {DL} says {D.he} never placed the order and was home.",
        state: [E(.digital, 3, "Order Record", "A phone number tied to {D} placed the order and used the lot address."), E(.statement, 2, "Victim's Statement", "{V} says the person had {D}'s build and a gray jacket.")],
        defense: [E(.statement, 1, "Home Alone", "{DL} says {D.he} was home and lent the phone.")],
        role: "Pizza driver",
        exam: [.direct("What is your job?", "\"I'm a pizza delivery driver, and I take orders to houses and apartments around the county.\""), .direct("What happened?", "\"An order sent me to an apartment lot, where a person stepped out, shoved me against my car, and took my cash.\""), .direct("How much was taken?", "\"Two hundred forty dollars in tips and delivery cash from my pouch.\""), .direct("What did the person look like?", "\"About the same build as {DL}, in a gray hooded sweatshirt, with a scarf over the lower face.\""), .direct("What does the order record show?", "\"A phone number tied to {DL} placed the order and gave the lot address.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was home and that {D.he} lent the phone to someone else that night.\""), .cross("You didn't see the person's face?", "\"No, a scarf covered it, and the lot light was weak.\""), .cross("The order was paid by phone?", "\"No, it was marked cash on delivery, so no card was used.\""), .cross("{DL} wasn't at the lot when you arrived?", "\"I didn't see {D.him}, only the person who took my cash.\""), .cross("The phone number is real?", "\"Yes, it belongs to {D.him}, and the carrier confirmed it.\""), .cross("You weren't badly hurt?", "\"No, I wasn't badly hurt, only bruised and shaken, but I couldn't work the next day.\"")],
        theory: ("{D} ordered a pizza and robbed the driver.", "A phone someone else used."),
        allocution: "\"I never placed that pizza order, and I was at home that evening. My cousin has used my phone number before, and I think that's how it ended up on the order. I'm sorry that {V} was shoved and robbed. I hope the right person is found, and I'd ask the court to look at my phone records.\"",
        truths: ("{DL} had a prior case in this court and was seen on a camera across the street minutes before.", "The order was placed from {DL}'s number while {DL}'s phone showed a different location, and a cousin who borrowed it later admitted the order."),
        defendant: [.direct("Did you rob the delivery driver?", "\"No. I was home that night. I lent my phone to a friend, who must have placed the order.\""), .direct("Who is the friend?", "\"A man who visits me sometimes. I'll tell the deputy his name today.\""), .direct("Why did you lend your phone?", "\"He said his battery was dead, and he needed to order food. I let him use it.\""), .direct("Do you own a gray sweatshirt?", "\"Yes, but so do half the men in this county.\""), .direct("What did you do when the deputy came?", "\"I told him the same thing, and I showed him the friend's number.\""), .direct("What would you tell the driver?", "\"I'm sorry for what happened. It wasn't me, and I'll help find the person.\""), .cross("You've been convicted of robbery before, haven't you?", "\"Yes, and I served what the court gave me for it. I'm trying to live honestly.\""), .cross("The order came from your phone and went to a lot where you live nearby?", "\"It did, and I understand why it points to me.\""), .cross("Your friend isn't an independent witness?", "\"He isn't an independent witness, and I know that, but he's honest.\""), .cross("You'll give the deputy your phone?", "\"Yes, I'll give the deputy my phone and the messages from my friend, today.\""), .cross("You'll stay away from the driver?", "\"Yes, I'll stay away from the driver and from his workplace, entirely.\"")],
        openings: ("A pizza order sent {V} to an apartment lot, where a person shoved {V} against the car and took $240 in tips and cash, and the phone number on the order was traced to {D}. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the phone record is in evidence.", "The defense will say {D} never placed the order and was home that night, and that a phone number on an order proves nothing about who stood in the lot. {D} did not rob anyone."),
        closings: ("The order that sent {V} to the lot came from a number traced to {D}, the shove and the taking followed, and since {PRIOR}, {DL} could not have missed how a delivery driver is lured.", "A number on an order can be used by anyone, and {D} was at home. The State must prove {D} was the person in the lot who shoved {V} and took the money."),
        timeline: [(0, "8 p.m.: the order comes in."), (0, "8:40 p.m.: the shove."), (1, "Deputies trace the number.")],
        identified: "The phone number on the order.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let trafficStopBribeBack = SmallCases.make(
        key: "story.followup.trafficStopBribeBack",
        category: .whiteCollar,
        headlines: ["Driver Offers Road Test Examiner $100 to Pass", "Defendant From Deputy Bribe Case Accused Again"],
        law: "bribery",
        spec: "Offered a thing of value to a public official, a driver's license examiner, to influence an official act, on {DATE}.",
        ages: 18...68,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} failed a commercial road test at a license office and then handed the examiner an envelope with $100, saying, 'Fix the score.' The examiner reported it. {DL} says the envelope was a tip for a long day.",
        state: [E(.physical, 3, "Envelope", "An envelope holding five $20 bills, handed over after the score sheet was marked.", .search), E(.statement, 2, "Examiner's Report", "The examiner wrote down the words used at the counter.")],
        defense: [E(.statement, 1, "A Tip", "{DL} says it was a thank-you for patience.")],
        role: "License examiner",
        exam: [.direct("What is your position?", "\"I'm a license examiner at a state office, where I give road tests to commercial drivers.\""), .direct("What happened at the test?", "\"A driver, {DL}, failed a commercial road test after missing a turn signal and rolling through a stop sign.\""), .direct("What did {DL} do afterward?", "\"{D.He} handed me an envelope with a hundred dollars and said, 'Fix the score.'\""), .direct("What was in the envelope?", "\"Five twenty-dollar bills, folded in half, handed to me after I'd marked the score sheet.\""), .direct("What did you do?", "\"I refused the envelope, wrote down what {D.he} said, and reported it to my supervisor and the sheriff.\""), .direct("What did {DL} say?", "\"{D.He} said it was a tip, a thank-you for my patience.\""), .cross("Tips aren't allowed?", "\"No, not for examiners, and it's posted at the desk.\""), .cross("{DL} said 'Fix the score'?", "\"Yes, in those words, after I had written the score.\""), .cross("{DL} was upset about failing?", "\"Yes, {D.he} was very upset about failing, and {D.he} argued for several minutes first.\""), .cross("{DL} didn't threaten you?", "\"No, {D.he} didn't threaten me. {D.He} only offered the envelope and asked for a favor.\""), .cross("{DL} left the envelope?", "\"I returned it, and the deputy took it into evidence.\"")],
        theory: ("{D} tried to buy a passing grade.", "A tip, badly timed."),
        allocution: "\"That envelope was a tip for a long day, and I thought it was a small gesture of thanks. I said something about fixing the sign, and I thought the test was over. I now understand how it looked to the examiner, and I'm sorry. I'll never hand money to a public official again.\"",
        truths: ("{DL} had a prior case in this court for the same act and asked the examiner whether the score could be changed.", "{DL} did not know it was against the rules, and a sign in the waiting room said tips were fine for the shuttle driver."),
        defendant: [.direct("Did you offer money to the examiner?", "\"I gave him an envelope as a thank-you for his patience. I didn't mean it as a bribe.\""), .direct("What did you say?", "\"I said I appreciated him and hoped he could help. I didn't say anything about the score.\""), .direct("Did you say 'Fix the score'?", "\"I may have. I was upset about failing, and I said it without thinking.\""), .direct("Why did you give a hundred dollars?", "\"It was what I had in my pocket. I thought it was a normal tip.\""), .direct("Did you know tips aren't allowed?", "\"I knew it was a government office, but I didn't think a thank-you was a crime.\""), .direct("What would you tell the examiner?", "\"I'm sorry for the envelope. I should have just thanked you.\""), .cross("You've been charged with offering money to an official before, haven't you?", "\"Yes, and I gave the court my word that it wouldn't happen a second time. I'm ashamed.\""), .cross("You gave money right after he marked your failing score?", "\"I did, and I can see why it looks like a bribe.\""), .cross("You said 'Fix the score'?", "\"I did say 'Fix the score,' and I regret it more than I can say.\""), .cross("You'll take the test again honestly?", "\"Yes, I'll take the road test again honestly, after I've practiced for a few weeks.\""), .cross("You'll never offer money to an official again?", "\"Never again. I'll never offer money to a public official, whatever the reason.\"")],
        openings: ("{D} failed a commercial road test at a license office and then handed the examiner an envelope with $100, saying, 'Fix the score,' and the examiner reported it. {DL} came before this court in {PRIORDATE} over {PRIOR}, and the envelope is in evidence.", "The defense will say the envelope was a tip for a long day, a thank-you for the examiner's patience. {D} meant nothing about the score and never asked to change it."),
        closings: ("The envelope held five twenty-dollar bills, it was handed over after the score sheet was marked, the words 'fix the score' were written down, and after {PRIOR} {DL} understood exactly what a license examiner may not accept.", "A tip for a long day is a courtesy, not a bribe, and the examiner changed nothing. The State must prove {D} meant the money to influence the score."),
        timeline: [(0, "Morning: {DL} fails the road test."), (0, "Noon: the envelope."), (0, "1 p.m.: deputies are called.")],
        identified: "The examiner's report.",
        mood: .indifferent)

    static let onePunchBack = SmallCases.make(
        key: "story.followup.onePunchBack",
        category: .publicOrder,
        headlines: ["Former Bouncer Swings at Heckler Outside Bowling Alley", "Defendant From Fatal Punch Case Charged With Disorderly Conduct"],
        law: "disorderly",
        spec: "Engaged in fighting and violent conduct in a public place, creating a risk of public alarm, on {DATE}.",
        ages: 23...46,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} was working a door at a bowling alley when a patron shouted insults. {DL} grabbed the patron's shirt and swung once but missed. The patron fell back and was unhurt. Deputies cited {D.him}. {DL} says {D.he} meant only to steer the patron out.",
