        exam: [.direct("What is your role?", "\"I'm the producer of a podcast, and I help the host prepare and publish each episode.\""), .direct("What was the episode about?", "\"An earlier case in this court involving {DL}, which our host discussed in a straightforward way.\""), .direct("What messages did the host receive?", "\"Three messages from one account, one of which said, 'Say my name again and you will regret it.'\""), .direct("How did the host react?", "\"{V.He} was frightened, and {V.he} reported it to the sheriff's office and asked for protection.\""), .direct("What do the network records show?", "\"That the account logged in from {DL}'s home internet connection.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was upset about the episode and didn't mean any of it.\""), .cross("The host mentioned {DL}'s name?", "\"Yes, in a factual way, as part of the case.\""), .cross("The messages were short?", "\"Yes, there were three messages over two days, and the middle one was the worst.\""), .cross("The account was anonymous?", "\"It used a made-up name, which made it harder for us to trace at first.\""), .cross("{DL} stopped after the deputy called?", "\"Yes, {D.he} stopped sending messages after the deputy called, and hasn't written since.\""), .cross("The host changed {V.his} routine?", "\"Yes, {V.he} changed {V.his} routine, and {V.he} installed cameras at the house.\"")],
        theory: ("{D} threatened a journalist.", "A hurt person who vented online."),
        allocution: "\"I sent one message, and I was angry. The podcast brought back a very painful time for me, and I wrote something I regret. I did not mean it as a threat. I'm sorry that it frightened {V}, and I'll stay off the internet when I'm upset.\"",
        truths: ("{DL} had a prior case in this court and searched where {V} lives after the episode.", "{DL} sent an apology to the show's inbox an hour later, which the producer saved."),
        defendant: [.direct("Did you send those messages?", "\"I sent them. I was upset about the episode, and I said something I didn't mean.\""), .direct("What did you mean by 'you will regret it'?", "\"I meant I'd complain about the show. I only meant to complain, not to threaten anybody.\""), .direct("Why did you use a made-up name?", "\"I didn't want my name attached to an angry message. I know that was cowardly.\""), .direct("Did you plan to follow the host?", "\"No. I never planned to do anything. I wrote it and sent it, and I felt sick.\""), .direct("What did you do when the deputy called?", "\"When the deputy called, I admitted it, and I promised not to write again.\""), .direct("What would you tell the host?", "\"I'm sorry for frightening you. I won't contact you again.\""), .cross("You've been charged with sending a threatening message before, haven't you?", "\"Yes, and the judge made me promise that this would not happen again. I'm ashamed.\""), .cross("'You will regret it' sounds like a threat, doesn't it?", "\"It does sound like a threat, and I understand that now.\""), .cross("You used your home connection?", "\"I did, and I know how that points to me.\""), .cross("You'll delete the account?", "\"Yes, I'll delete the account, and every message that I sent from it.\""), .cross("You'll avoid the podcast?", "\"Yes, I'll avoid the podcast and the host, and I won't mention {V.him} again.\"")],
        openings: ("{V}, a podcast host, received messages after an episode about {D}'s earlier case, and one said, 'Say my name again and you will regret it,' and the account was traced to {D}'s home network, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say the message was angry venting, not a threat, and {D} never meant to hurt the host. {D} never contacted {V} again."),
        closings: ("The message told the host to regret saying a name again, it came from {D}'s home network, and after {PRIOR} {DL} understood exactly how a host would read it.", "Venting after hearing yourself discussed in a podcast is human, and no one was harmed. The State must prove {D} wanted the host to fear harm, and a message written in anger after hearing the episode does not show that."),
