        state: [E(.document, 3, "Promissory Note", "A signed note promising 8 percent a year with no risk."), E(.document, 2, "Bank Records", "The $60,000 deposited to {D}'s personal account.")],
        defense: [E(.statement, 1, "Delayed Co-op", "{DL} says the co-op was slow to open.")],
        role: "Victim's adult child",
        exam: [.direct("How are you related to the victim?", "\"The victim is my father, who is seventy-six and retired, and I help {V.him} with {V.his} finances.\""), .direct("What did you learn?", "\"That my father gave {DL} sixty thousand dollars for what {D.he} called a guaranteed investment in a farm co-op.\""), .direct("What does the promissory note say?", "\"That {DL} would pay eight percent a year, with no risk, and the note carries {D.his} signature.\""), .direct("What did you find out about the co-op?", "\"That it doesn't exist. There is no farm co-op by that name, and no property or business.\""), .direct("Where did the money go?", "\"Into {DL}'s personal checking account, according to the bank records.\""), .direct("What did {DL} say?", "\"{D.He} said the co-op was slow to open and that {D.he} was still working on it.\""), .cross("Your father wanted a safe investment?", "\"Yes, my father wanted a safe investment, and {DL} used the word guaranteed several times.\""), .cross("{DL} gave him paperwork?", "\"Yes, {D.he} gave him the promissory note and a glossy brochure about the co-op.\""), .cross("{DL} has paid him anything?", "\"No, {D.he} hasn't paid my father a single dollar, not even the first interest payment.\""), .cross("Your father trusted {DL}?", "\"Yes, my father trusted {D.him} because {D.he} spoke at {V.his} church on Sundays.\""), .cross("Your father is embarrassed?", "\"Very embarrassed, and {V.he} wouldn't tell me about it for several weeks.\"")],
        theory: ("{D} sold a fake investment.", "An investment that was late."),
