        mood: .wantsConviction)

    static let chopShopBack = SmallCases.make(
        key: "story.followup.chopShopBack",
        category: .property,
        headlines: ["Farm Tractor Trailers Found on Lot of Equipment Dealer", "Defendant From Chop Shop Case Charged With Possessing Stolen Property"],
