        spec: "Possessed three stolen farm trailers, valued at $9,000, knowing or having reason to believe they were stolen, on {DATE}.",
        ages: 38...58,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, deputies found three flatbed farm trailers with filed-off serial numbers on {D}'s equipment lot, one of them stolen from {V}'s farm. {DL} says {D.he} bought them at an auction with a bill of sale.",
        state: [E(.physical, 3, "Trailers", "Three trailers with ground-off serial numbers.", .search), E(.forensic, 2, "Hidden Number", "A lab restored the stamp on one frame matching {V}'s trailer.")],
        defense: [E(.document, 1, "Bill of Sale", "A bill of sale for the trailers from an auction company.")],
        role: "Farm owner",
        exam: [.direct("What is your farm?", "\"I run a farm, where I keep equipment and trailers for hauling hay and livestock.\""), .direct("What was taken?", "\"A flatbed farm trailer worth about three thousand dollars, which I kept in a barn lot.\""), .direct("What did deputies find?", "\"Three flatbed trailers on {DL}'s equipment lot, each with the serial numbers ground off.\""), .direct("How was your trailer identified?", "\"A lab restored a stamped number on one frame, and it matched my trailer's number exactly.\""), .direct("What was {DL}'s business?", "\"An equipment lot, where {D.he} buys and sells used farm gear.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} bought them at an auction and has a bill of sale.\""), .cross("The bill of sale is from an auction company?", "\"Yes, it's from an auction company, but it doesn't list any serial numbers.\""), .cross("Trailers are common at auctions?", "\"Yes, trailers are common at auctions, and many look alike from a distance.\""), .cross("Your trailer was missing for weeks?", "\"Yes, my trailer was missing for weeks, from the day it was taken.\""), .cross("The other two trailers belong to others?", "\"Not yet identified, as far as I know, though the deputies are still checking.\""), .cross("{DL} gave your trailer back?", "\"Yes, {D.he} gave it back, after the deputy confirmed that it was mine.\"")],
        theory: ("{D} held stolen trailers.", "A buyer who trusted a bill of sale."),
        allocution: "\"I bought those trailers at an auction with a bill of sale, and they were already missing their serial numbers. I did not know one was stolen from a farm. I'm sorry to {V} for the loss. I'll give back what's {V.his} and I'll walk away from any deal without paperwork.\"",
        truths: ("{DL} had a prior case in this court and paid half the market price in cash.", "The auction company no longer exists and {DL} wrote down the plates of the truck that dropped them off."),
        defendant: [.direct("Did you know the trailers were stolen?", "\"No. I bought them at an auction and I have the bill of sale. I'd never knowingly buy stolen trailers.\""), .direct("Which auction was it?", "\"A farm auction two counties over. I go every month, and I bought three trailers that day.\""), .direct("Why were the serial numbers ground off?", "\"They were that way when I bought them. I didn't look closely, and I thought it was just rust.\""), .direct("Did you grind them off yourself?", "\"No. I'd never do that. I don't even own a grinder.\""), .direct("What did you do when the deputy found them?", "\"I handed over my paperwork and told him which auction company I'd used.\""), .direct("What would you tell the farm owner?", "\"I'm sorry for your loss. I'll return your trailer, and I'll help find who sold it.\""), .cross("You've been convicted of possessing stolen equipment before, haven't you?", "\"Yes, and I told the court I'd always check serial numbers. I didn't check these.\""), .cross("Three trailers with ground-off numbers should have raised a flag?", "\"They should have, and I made a mistake by not asking more questions.\""), .cross("Your bill of sale doesn't list serial numbers?", "\"It doesn't list serial numbers, and I know that makes it a weak document.\""), .cross("You'll give the auction company's records to the deputy?", "\"Yes, I'll give the auction company's records to the deputy, today.\""), .cross("You'll return the other two trailers if they're identified?", "\"Yes. If their owners can show titles, I will have them trucked back at my own cost.\"")],
        openings: ("Deputies found three flatbed farm trailers with filed-off serial numbers on {D}'s equipment lot, one of them stolen from {V}'s farm, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} bought the trailers at an auction with a bill of sale, and did not know any were stolen. {D} filed no numbers off."),
        closings: ("Three trailers carried filed-off serial numbers on {D}'s lot and one was {V}'s, and with {PRIOR} behind {D.him}, {DL} knew what a filed number means.", "A bill of sale from an auction is an honest purchase. The State must prove {D} knew the trailer was stolen, and an auction's bill of sale is what an honest dealer relies on."),
        timeline: [(-30, "The trailer is stolen."), (0, "Morning: deputies visit the lot."), (0, "Noon: the numbers are checked.")],
        identified: "Deputies matched the restored stamp.",
        mood: .wantsConviction)

    static let odometerRollbackBack = SmallCases.make(
