    static let stolenValorBack = SmallCases.make(
        key: "story.followup.stolenValorBack",
        category: .whiteCollar,
        headlines: ["Fundraiser Collected $4,000 for Fake Wounded-Veteran Fund", "Defendant From Stolen Valor Case Faces New Fraud Charge"],
