        ages: 44...66,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} asked {V}, the treasurer of a small church, for a $4,000 gift for a wounded veteran's medical bills. The veteran named did not exist. {DL} says the money was set aside and a family later declined it.",
        state: [E(.document, 3, "Church Check", "A $4,000 check made out to {D}."), E(.statement, 2, "Veteran Check", "No veteran by that name exists in any county record.")],
        defense: [E(.statement, 1, "Family Declined", "{DL} says the family declined the gift.")],
        role: "Church treasurer",
        exam: [.direct("What is your role?", "\"I'm the treasurer of a small church, and I handle the donations and the checks.\""), .direct("What did {DL} ask you for?", "\"A four-thousand-dollar gift for a wounded veteran's medical bills, with a story about a young man hurt overseas.\""), .direct("What did you do?", "\"I wrote a check for four thousand dollars, made out to {DL}, after the board agreed.\""), .direct("What did you learn later?", "\"That no veteran by that name exists in any county record, and no one knew the story.\""), .direct("What does the check show?", "\"A four-thousand-dollar check made out to {DL}, cashed the next day.\""), .direct("What did {DL} say?", "\"{D.He} said the family declined the gift, so {D.he} set the money aside.\""), .cross("{DL} told a moving story?", "\"Yes, {D.he} told a moving story, and several members cried when {D.he} told it.\""), .cross("{DL} didn't give a name?", "\"{D.He} gave a first name only, and wouldn't say where the man lived.\""), .cross("{DL} showed you a photo?", "\"A photo of a man in uniform, which turned out to be from the internet.\""), .cross("{DL} hasn't returned the money?", "\"No, {D.he} didn't show me any papers, only a photo and a story.\""), .cross("{DL} attends the church?", "\"Occasionally, {D.he} comes on Sundays, but {D.he} isn't a regular member.\"")],
        theory: ("{D} invented a wounded veteran.", "A charity that fell through."),
        allocution: "\"A friend's cousin told me about a veteran who needed help, and I asked {V} for money in good faith. The money was saved in an account for safekeeping, and a family later declined it. I'm sorry that it looked like I invented a veteran. I'll give every dollar back to {V}.\"",
        truths: ("{DL} had a prior case in this court and deposited the check into a personal account.", "The money sat in a savings account until {DL} gave it back to the church."),
        defendant: [.direct("Did you lie about a wounded veteran?", "\"I told a story about a veteran I'd heard about. I meant to help him, but I couldn't find him.\""), .direct("Who was the veteran?", "\"A man I met once at a hospital. I never got his last name.\""), .direct("What did you do with the money?", "\"I kept it set aside, I told myself, but I spent some on bills.\""), .direct("Did you show a photo?", "\"A picture I found, to put a face to the story. I know that was wrong.\""), .direct("Why didn't you return it?", "\"I was embarrassed. I planned to repay it, and I put it off.\""), .direct("What would you tell the church?", "\"I'm sorry for the story and the money. I'll repay every dollar.\""), .cross("You've been convicted of fraud before, haven't you?", "\"Yes, and I said then that I'd never be back here again. I'm ashamed.\""), .cross("No veteran by that name exists in any record?", "\"That's what they say, and I can't prove otherwise, though I want to.\""), .cross("You took four thousand dollars from a church?", "\"I did take four thousand dollars from a church, and I can't excuse it.\""), .cross("You'll repay it?", "\"Yes, I'll repay the full amount to the church, as soon as I can.\""), .cross("You'll stay away from the church?", "\"Yes, I'll stay away from the church, and from every other one.\"")],
        openings: ("{D} asked {V}, the treasurer of a small church, for a $4,000 gift for a wounded veteran's medical bills, and the veteran named did not exist, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the money was set aside and a family later declined it, and {D} meant to deliver it. {D} did not spend a dollar."),
