    static let boatLandingBack = SmallCases.make(
        key: "story.followup.boatLandingBack",
        category: .property,
        headlines: ["Fisherman's Boat Damaged With Hammer at Marina Slip", "Defendant From Boat Ramp Fight Charged With Property Damage"],
