        state: [E(.video, 3, "Dock Camera", "A person with a hammer smashes the windshield and leaves."), E(.physical, 2, "Hammer", "A hammer with glass chips in the boat's cooler.", .search)],
        defense: [E(.statement, 1, "Offshore", "{DL} says {D.he} was fishing that morning.")],
        role: "Marina dockhand",
        exam: [.direct("What is your position?", "\"I'm a dockhand at the marina, and I look after the boats and the slips.\""), .direct("What did you find?", "\"A fishing boat with a smashed windshield and a cracked console, at its slip, early in the morning.\""), .direct("What does the dock camera show?", "\"A person with a hammer smashing the windshield, then walking away down the dock.\""), .direct("What was found?", "\"A hammer with glass chips, in the boat's cooler, which deputies took as evidence.\""), .direct("Why do you suspect {DL}?", "\"The boat's owner told me {D.he} had argued with {DL} about a mooring spot a few days earlier.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was fishing offshore that morning, miles away.\""), .cross("The person's face isn't visible?", "\"No, the hood and the angle hid the face, and the video is dark.\""), .cross("{DL} keeps a boat at the marina?", "\"Yes, {D.he} keeps a boat in a slip a few doors down from the owner's.\""), .cross("{DL} was seen offshore?", "\"I didn't see {D.him} leave that morning, and I didn't see {D.him} return.\""), .cross("A hammer is a common tool?", "\"Yes, a hammer is a common tool, and many boaters carry one.\""), .cross("The owner and {DL} argued?", "\"Yes, they argued loudly about a mooring spot, a few days earlier.\"")],
        theory: ("{D} smashed a rival's boat.", "A fisherman who was offshore."),
        allocution: "\"I was fishing offshore that morning, and I did not smash that boat. We had argued over a shared slip, and I'm sorry that it was hard between us. I'd never take a hammer to someone's boat. I hope the person is found, and I'd ask the court to check the marina's records.\"",
        truths: ("{DL} had a prior case in this court and told {V} 'next time it's the boat.'", "{DL}'s boat was gone from its slip an hour before the damage, per the harbor log."),
